(function(){const e=LW.tiles,p="#1f2b45";function g(n){const a=n.some(b=>b[0]==="*");let t=0,u=2,i="";return n.forEach((b,s)=>{const v=b[0]==="*",r=b[0]==="#",q=v||r?b.slice(1):b,x=Math.round(q.replace(/[{}]/g,"").length*9.2+22);t&&t+x>320&&(t=0,u+=46);const d=`x="${t+2}" y="${u}" width="${x}" height="38" rx="10"`;i+=v?`<rect class="tp" data-id="w${s}" onclick="lnTap(this)" ${d}/>`:a?`<rect class="tpx" data-id="x${s}" onclick="lnTap(this)" ${d}/>`:`<rect ${d} fill="${r?"#fff1b8":"#fff"}" stroke="${p}" stroke-width="2.4"/>`;const N=q.replace(/\{([^}]+)\}/g,'<tspan style="fill:#e8453c">$1</tspan>');i+=`<text x="${t+2+x/2}" y="${u+25}" text-anchor="middle" class="ln-svgtxt" pointer-events="none">${N}</text>`,t+=x+8}),LW.svg(324,u+38+2,i,340)}const C=["a","ă","â","b","c","d","đ","e","ê","g","h","i","k","l","m","n","o","ô","ơ","p","q","r","s","t","u","ư","v","x","y"],B=["a","á","ớ","bê","xê","dê","đê","e","ê","giê","hát","i","ca","e-lờ","em-mờ","en-nờ","o","ô","ơ","pê","quy","e-rờ","ét-xì","tê","u","ư","vê","ích-xì","i dài"];function k(n){n=n||{};const o=6,h=50,m=n.names?58:46,a=4;let t="";C.forEach((i,b)=>{const s=2+b%o*(h+a),v=2+Math.floor(b/o)*(m+a),r=`x="${s}" y="${v}" width="${h}" height="${m}" rx="9"`;t+=n.tap?`<rect class="${n.tap.includes(i)?"tp":"tpx"}" data-id="c${b}" onclick="lnTap(this)" ${r}/>`:`<rect ${r} fill="#fff" stroke="${p}" stroke-width="2"/>`,t+=`<text x="${s+h/2}" y="${v+(n.names?28:31)}" text-anchor="middle" class="ln-svgtxt" style="font-size:24px" pointer-events="none">${i}</text>`,n.names&&(t+=`<text x="${s+h/2}" y="${v+49}" text-anchor="middle" class="ln-svgtxt" style="font-size:12px;fill:#3d6ef7" pointer-events="none">${B[b]}</text>`)});const u=Math.ceil(C.length/o);return LW.svg(o*(h+a),u*(m+a),t,330)}const M=(()=>{let h="";const m=(a,t,u,i)=>`<rect x="${a}" y="${t}" width="156" height="${u}" fill="${i}" stroke="${p}" stroke-width="2"/>`;return h+=m(2,2,36,"#ffe3e3")+m(158,2,36,"#e6edff"),h+=`<text x="${2+156/2}" y="26" text-anchor="middle" class="ln-svgtxt" style="font-size:14px">Trước i, e, ê</text>`,h+=`<text x="${2+156*1.5}" y="26" text-anchor="middle" class="ln-svgtxt" style="font-size:14px">Trước chữ còn lại</text>`,[["k","c"],["gh","g"],["ngh","ng"]].forEach(([a,t],u)=>{const i=38+u*44;h+=m(2,i,44,"#fff7f7")+m(158,i,44,"#fff"),h+=`<text x="${2+156/2}" y="${i+30}" text-anchor="middle" class="ln-svgtxt" style="font-size:24px;fill:#e8453c">${a}</text>`,h+=`<text x="${2+156*1.5}" y="${i+30}" text-anchor="middle" class="ln-svgtxt" style="font-size:24px;fill:#3d6ef7">${t}</text>`}),LW.svg(316,174,h,330)})(),c=(n,o)=>`<div style="background:#fffdf3;border:2px solid #f1d48a;border-radius:14px;padding:12px 14px;text-align:left;line-height:1.65;font-size:16px;color:${p}">${n?`<div style="text-align:center;font-weight:800;font-size:17px;margin-bottom:4px">${n}</div>`:""}${o}</div>`,T=n=>n.replace(/ /g," "),w=n=>({order:n.map(T),ans:n.map(T).join(" ")}),y=c("Mùa hè của Nam","Mùa hè, Nam được nghỉ học. Mỗi sáng, Nam cùng bà ra vườn tưới rau. Chú chó Vàng lon ton chạy theo. Buổi chiều, Nam ngồi bên hiên đọc truyện cho bà nghe. Bà cười hiền: “Mùa hè này, cháu bà lớn hẳn lên!”"),l=c("Sẻ con tập bay","Sẻ con tập bay. Lần đầu, Sẻ vừa rời tổ đã rơi xuống bụi cỏ. Sẻ hơi buồn nhưng không bỏ cuộc. Ngày nào Sẻ cũng tập, đôi cánh cứng cáp dần. Một buổi sáng, Sẻ bay vút lên ngọn cây cao. Mẹ Sẻ vui mừng: “Con giỏi lắm! Chăm tập thì sẽ làm được.”");LEARN.add({id:"hoc-tv2",grade:2,name:"Tiếng Việt 2",icon:"📖",who:"rabbit",color:"#12b26e",title:"Tiếng Việt lớp 2 — học cả năm",blurb:"Từ ngữ, câu, chính tả, đọc hiểu và viết đoạn văn: giảng ngắn, làm thử ngay, luyện 5 câu nhận sao."},[{id:"chinhta",name:"Chính tả",en:"Spelling",icon:"✏️",color:"#ff6b6b",lessons:[{id:"tv2.ct-chucai",title:"Bảng chữ cái",emoji:"🔤",min:5,who:"owl",cards:[{t:"say",pose:"wave",text:"Chào em, Cú Giáo Sư đây! Tiếng Việt có <b>29 chữ cái</b>. Mỗi chữ cái có một <b>tên</b> riêng, như mỗi bạn trong lớp có một cái tên."},{t:"pic",svg:k({names:!0}),cap:"Bảng 29 chữ cái, xếp đúng thứ tự. Dòng chữ nhỏ màu xanh là <b>tên chữ</b>."},{t:"say",text:"Có chữ đọc tên giống hệt mặt chữ: a, o, ô. Nhưng nhiều chữ có tên khác hẳn: chữ <b>k</b> tên là <b>ca</b>, chữ <b>q</b> tên là <b>quy</b>, chữ <b>y</b> tên là <b>i dài</b>."},{t:"try",q:{text:"Chữ cái <b>g</b> có tên là gì?",opts:["gờ","giê","ghê","gi"],ans:1,hint:"Nhìn lại bảng chữ cái, tìm chữ g rồi đọc dòng tên ở dưới.",why:'Chữ g tên là <b>giê</b>. Còn "gờ" là cách đọc âm khi ghép vần, không phải tên chữ.'}},{t:"tap",text:'Có những chữ cái được "đội mũ", "mọc râu" hay có gạch ngang. Chạm vào tất cả các chữ đó.',svg:k({tap:["ă","â","đ","ê","ô","ơ","ư"]}),need:7,done:"Đó là <b>ă, â, đ, ê, ô, ơ, ư</b>. Mỗi chữ là một chữ cái riêng, không phải chữ a, d, e, o, u thêm dấu thanh."},{t:"say",text:"Thứ tự chữ cái rất có ích: danh sách lớp, từ điển đều xếp theo thứ tự này. Em nhớ các nhóm: <b>a – ă – â</b>, <b>d – đ</b>, <b>e – ê</b>, <b>o – ô – ơ</b>, <b>u – ư</b>."},{t:"steps",title:"Ví dụ: Xếp tên các bạn theo thứ tự bảng chữ cái: Hà, Bình, Dũng, An.",items:[{text:"Nhìn <b>chữ cái đầu</b> của mỗi tên: H, B, D, A."},{text:"Tìm trong bảng xem chữ nào đứng trước: A, rồi B, rồi D, rồi H."},{text:"Xếp được: <b>An, Bình, Dũng, Hà</b>."}]},{t:"try",q:{text:"Xếp các tên sau theo thứ tự bảng chữ cái.",order:["Cúc","Đức","Lan","Mai"],ans:"Cúc Đức Lan Mai",hint:"Nhìn chữ cái đầu: C, Đ, L, M. Chữ nào đứng trước trong bảng?",why:"C đứng trước Đ, Đ đứng trước L, L đứng trước M. Thứ tự: Cúc, Đức, Lan, Mai."}},{t:"try",q:{text:"Chữ cái nào đứng <b>ngay sau</b> chữ <b>đ</b>?",opts:["d","e","ê","g"],ans:1,hint:"Đọc thầm bảng chữ cái: … c, d, đ, …",why:"Thứ tự là: d, đ, e, ê. Ngay sau đ là <b>e</b>. Chữ d đứng <b>trước</b> đ."}},{t:"tip",text:"• Tiếng Việt có <b>29 chữ cái</b>.<br>• Nhớ tên các chữ khó: k (ca), q (quy), y (i dài), r (e-rờ), s (ét-xì), x (ích-xì).<br>• ă, â đứng sau a; đ sau d; ê sau e; ô, ơ sau o; ư sau u.<br>• Xếp tên theo thứ tự: so <b>chữ cái đầu</b> trước."}],practice:[{id:"tv2.ct-chucai.1",text:"Tiếng Việt có bao nhiêu chữ cái?",opts:["24 chữ","26 chữ","29 chữ","30 chữ"],ans:2,why:"Bảng chữ cái tiếng Việt có <b>29 chữ</b>, từ a đến y. (26 chữ là bảng chữ cái tiếng Anh.)"},{id:"tv2.ct-chucai.2",text:"Chữ cái <b>x</b> có tên là gì?",opts:["ích-xì","ét-xì","xờ","xê"],ans:0,why:"Chữ x tên là <b>ích-xì</b>. Còn ét-xì là tên chữ s, xê là tên chữ c."},{id:"tv2.ct-chucai.3",text:"Chữ cái nào đứng <b>ngay trước</b> chữ <b>i</b>?",opts:["k","g","h","ê"],ans:2,why:"Thứ tự là: g, h, i, k. Ngay trước i là <b>h</b>."},{id:"tv2.ct-chucai.4",text:"Xếp các tên sau theo thứ tự bảng chữ cái.",order:["Ân","Bảo","Oanh","Tuấn"],ans:"Ân Bảo Oanh Tuấn",why:"Chữ cái đầu là Â, B, O, T. Trong bảng: â đứng trước b, b trước o, o trước t. Thứ tự: Ân, Bảo, Oanh, Tuấn."},{id:"tv2.ct-chucai.5",text:"Chữ cái có tên là <b>quy</b> là chữ nào? Gõ chữ cái đó.",input:!0,ans:"q",why:"<b>quy</b> là tên của chữ <b>q</b>. Chữ q luôn đi cùng u: quả, quê, quạt."}]},{id:"tv2.ct-ckg",title:"Viết c hay k, g hay gh, ng hay ngh",emoji:"🐟",min:5,who:"cat",cards:[{t:"say",pose:"wave",text:'Chào em, Mèo Miu đây! Cùng một âm "cờ" mà có lúc viết <b>c</b> (con cá), có lúc viết <b>k</b> (cái kéo). Làm sao biết? Có một <b>bí kíp</b> nhỏ thôi!'},{t:"pic",svg:M,cap:"Gặp <b>i, e, ê</b> đứng ngay sau thì viết <b>k, gh, ngh</b>. Còn lại viết <b>c, g, ng</b>."},{t:"pic",svg:g(["{k}im","{k}ẻ","{k}ể","{c}á","{c}ờ","{c}ủ"]),cap:"kim, kẻ, kể: sau là i, e, ê → <b>k</b>. cá, cờ, củ: sau là a, ơ, u → <b>c</b>."},{t:"try",q:{text:'Điền <b>c</b> hay <b>k</b>: "thước …ẻ". Gõ chữ cần điền.',input:!0,ans:"k",hint:"Nhìn chữ đứng ngay sau chỗ trống. Đó có phải là e không?",why:"Sau chỗ trống là <b>e</b>, nên viết <b>k</b>: thước kẻ."}},{t:"say",text:"Bí kíp này dùng luôn cho <b>g/gh</b> và <b>ng/ngh</b>: ghế, ghi, nghe, nghỉ có <b>h</b>; còn gà, gỗ, ngõ, ngủ thì không có h."},{t:"try",q:{text:"Từ nào viết <b>đúng</b> chính tả?",opts:["ngỉ hè","nghỉ hè","ghỉ hè"],ans:1,hint:"Chữ đứng sau là i. Trước i ta viết ng hay ngh?",why:"Trước <b>i</b> phải viết <b>ngh</b>: nghỉ hè."}},{t:"steps",title:"Cách làm khi phân vân",items:[{text:"Bước 1: Nhìn chữ <b>ngay sau</b> chỗ cần điền."},{text:"Bước 2: Là <b>i, e, ê</b> → chọn k, gh, ngh."},{text:"Bước 3: Là chữ khác (a, o, ô, ơ, u, ư…) → chọn c, g, ng."},{text:'Ví dụ: "con …ỗng": sau là ô → viết <b>ng</b>: con ngỗng. "…é thăm": sau là e → viết <b>gh</b>: ghé thăm.'}]},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:g(["Bé","ngồi","trên","*gế","*nge","bà","kể","chuyện","*kổ","tích."]),need:3,done:'Sửa lại: gế → <b>ghế</b>, nge → <b>nghe</b>, kổ → <b>cổ</b>. Còn "kể" viết đúng vì sau k là ê.'},{t:"try",q:{text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Bố đóng cái gế gỗ.","Bố đóng cái ghế ghỗ.","Bố đóng cái ghế gỗ."],ans:2,hint:"Xét từng tiếng: sau chỗ đó là ê hay ô?",why:'"ghế": sau là ê nên có h. "gỗ": sau là ô nên không có h. Câu đúng: Bố đóng cái ghế gỗ.'}},{t:"tip",text:"• <b>k, gh, ngh</b> đứng trước <b>i, e, ê</b>: kim, kẻ, ghế, nghe.<br>• <b>c, g, ng</b> đứng trước các chữ còn lại: cá, gà, ngõ.<br>• Phân vân thì nhìn chữ <b>ngay sau</b> chỗ trống."}],practice:[{id:"tv2.ct-ckg.1",text:'Điền <b>c</b> hay <b>k</b>: "con …iến".',opts:["c","k"],ans:1,why:"Sau chỗ trống là <b>i</b> nên viết <b>k</b>: con kiến."},{id:"tv2.ct-ckg.2",text:"Từ nào viết <b>sai</b> chính tả?",opts:["ghi nhớ","gà gáy","gỗ lim","gế đá"],ans:3,why:"Trước <b>ê</b> phải viết <b>gh</b>: ghế đá. Các từ còn lại đều đúng."},{id:"tv2.ct-ckg.3",text:'Điền <b>ng</b> hay <b>ngh</b>: "bé …e lời mẹ".',opts:["ngh","ng"],ans:0,why:"Sau chỗ trống là <b>e</b> nên viết <b>ngh</b>: nghe lời mẹ."},{id:"tv2.ct-ckg.4",text:'Điền <b>c</b> hay <b>k</b>: "Em …ể chuyện cho bà nghe." Gõ chữ cần điền.',input:!0,ans:"k",why:"Sau chỗ trống là <b>ê</b> nên viết <b>k</b>: kể chuyện."},{id:"tv2.ct-ckg.5",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Cô giáo cể chuyện con nghé.","Cô giáo kể chuyện con ngé.","Cô giáo kể chuyện con nghé.","Kô giáo kể chuyện con nghé."],ans:2,why:'"Cô": sau là ô → c. "kể": sau là ê → k. "nghé": sau là e → ngh.'}]},{id:"tv2.ct-chtr-sx",title:"Viết ch hay tr, s hay x",emoji:"🎋",min:5,who:"fox",cards:[{t:"say",pose:"wave",text:'Chào em, Cáo Bo đây! Nhiều bạn đọc "che" và "tre" nghe gần giống nhau nên hay viết nhầm. Nhưng nghĩa thì khác hẳn đó!'},{t:"pic",svg:e([["☂️","che ô"],["🎋","cây tre"],["🍋","quả chanh"],["🥁","cái trống"]]),cap:"<b>ch</b>: che, chanh · <b>tr</b>: tre, trống. Đổi chữ là đổi nghĩa."},{t:"say",text:"<b>ch/tr</b> không có quy tắc như c/k. Bí kíp: <b>hiểu nghĩa</b> của từ, đọc nhiều và nhớ mặt chữ."},{t:"try",q:{text:'Chọn tiếng đúng: "Cả lớp … chỉ học bài."',opts:["trăm","chăm"],ans:1,hint:"Từ này nghĩa là siêng năng. Còn tiếng kia là một con số.",why:'<b>chăm chỉ</b> (siêng năng) viết ch. Còn "trăm" là số: một trăm.'}},{t:"say",text:"Cặp <b>s/x</b> cũng vậy: <b>sâu</b> (con sâu) khác <b>xâu</b> (xâu kim); <b>sẻ</b> (chim sẻ) khác <b>xẻ</b> (xẻ gỗ)."},{t:"pic",svg:e([["⭐","ngôi sao"],["🐦","chim sẻ"],["🚲","xe đạp"],["🧵","xâu kim"]]),cap:"<b>s</b>: sao, sẻ · <b>x</b>: xe, xâu."},{t:"try",q:{text:'Điền <b>s</b> hay <b>x</b>: "Bầu trời …anh biếc."',opts:["s","x"],ans:1,hint:"Đây là từ chỉ màu sắc của bầu trời.",why:"<b>xanh</b> biếc: màu xanh viết <b>x</b>."}},{t:"steps",title:"Mẹo nhớ mặt chữ",items:[{text:"Nhớ theo cặp hai tiếng cùng âm đầu: <b>che chở</b>, <b>trong trẻo</b>, <b>sạch sẽ</b>, <b>xinh xắn</b>."},{text:'Phân vân thì đặt từ vào câu, xem nghĩa có hợp không: "mẹ <b>chở</b> em" (đưa đi bằng xe) khác "<b>trở</b> về" (quay lại).'},{text:"Đọc sách nhiều, nhìn kĩ mặt chữ. Gặp từ chưa chắc thì hỏi cô, hỏi bố mẹ."}]},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:g(["Sáng","sớm,","mẹ","*trở","em","đến","*chường.","Hai","bên","đường,","hàng","cây","*sanh","mát."]),need:3,done:'Sửa lại: mẹ <b>chở</b> em, đến <b>trường</b>, cây <b>xanh</b>. "trở" cũng là một từ (trở về), nhưng ở đây mẹ <b>chở</b> em đi.'},{t:"try",q:{text:'Điền <b>ch</b> hay <b>tr</b>: "Tiếng …ống trường vang lên." Gõ chữ cần điền.',input:!0,ans:"tr",hint:"Đó là cái trống bác bảo vệ đánh báo giờ vào lớp.",why:"<b>trống</b> trường viết <b>tr</b>."}},{t:"tip",text:"• ch/tr, s/x không có quy tắc chung: phải <b>hiểu nghĩa</b> và <b>nhớ mặt chữ</b>.<br>• Nhớ theo cặp: che chở, trong trẻo, sạch sẽ, xinh xắn.<br>• Phân vân thì đặt từ vào câu, xem nghĩa có hợp không."}],practice:[{id:"tv2.ct-chtr-sx.1",text:'Điền <b>ch</b> hay <b>tr</b>: "quả …anh".',opts:["tr","ch"],ans:1,why:"<b>quả chanh</b> viết ch."},{id:"tv2.ct-chtr-sx.2",text:"Từ nào viết <b>đúng</b> chính tả?",opts:["se đạp","sân chường","xe đạp","chường học"],ans:2,why:"Viết đúng là: <b>xe đạp</b>, sân <b>trường</b>, <b>trường</b> học."},{id:"tv2.ct-chtr-sx.3",text:'Điền <b>s</b> hay <b>x</b>: "Chú chim …ẻ đậu trên cành."',opts:["s","x"],ans:0,why:'<b>chim sẻ</b> viết s. Còn "xẻ" là cưa ra, như xẻ gỗ.'},{id:"tv2.ct-chtr-sx.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Bé chồng cây trên sân.","Bé trồng cây trên xân.","Bé chồng cây trên xân.","Bé trồng cây trên sân."],ans:3,why:"<b>trồng</b> cây viết tr, <b>sân</b> viết s: Bé trồng cây trên sân."},{id:"tv2.ct-chtr-sx.5",text:'Điền <b>s</b> hay <b>x</b>: "Mẹ mua cho em đôi giày …inh xắn." Gõ chữ cần điền.',input:!0,ans:"x",why:"<b>xinh xắn</b>: cả hai tiếng đều viết x."}]},{id:"tv2.ct-drgi-ln",title:"Viết d, gi hay r; l hay n",emoji:"🍃",min:5,who:"bear",cards:[{t:"say",pose:"wave",text:"Chào em, Gấu Mít đây! Ở nhiều nơi, người ta đọc <b>d, gi, r</b> gần giống nhau; <b>l</b> và <b>n</b> cũng dễ lẫn. Khi viết, phải chọn đúng chữ thì từ mới đúng nghĩa."},{t:"pic",svg:e([["🥿","đôi dép"],["👟","đôi giày"],["🐢","con rùa"],["🥬","rổ rau"]]),cap:"<b>d</b>: dép · <b>gi</b>: giày · <b>r</b>: rùa, rổ, rau."},{t:"try",q:{text:'Điền <b>d</b>, <b>gi</b> hay <b>r</b>: "cơn …ó thổi mát".',opts:["d","gi","r"],ans:1,hint:"Từ này nói về thứ làm lá cây rung rinh.",why:"<b>cơn gió</b> viết gi."}},{t:"say",text:"Còn <b>l</b> và <b>n</b>: <b>lo</b> (lo lắng) khác <b>no</b> (ăn no); <b>lắng</b> nghe khác trời <b>nắng</b>."},{t:"pic",svg:e([["🍃","lá cây"],["🌾","bông lúa"],["👒","nón lá"],["💧","giọt nước"]]),cap:'<b>l</b>: lá, lúa · <b>n</b>: nón, nước. "nón lá" có cả n và l!'},{t:"try",q:{text:"Từ nào viết <b>đúng</b> chính tả?",opts:["uống lước","lấu cơm","nấu cơm","nón ná"],ans:2,hint:"Nhớ: nước, nấu, nón lá.",why:"Viết đúng là: uống <b>nước</b>, <b>nấu</b> cơm, nón <b>lá</b>."}},{t:"steps",title:"Mẹo nhớ theo cặp",items:[{text:"Hai tiếng cùng <b>l</b>: lo lắng, lấp lánh, long lanh."},{text:"Hai tiếng cùng <b>n</b>: nắn nót, no nê, nết na."},{text:"Hai tiếng cùng <b>d</b>, <b>gi</b>, <b>r</b>: dịu dàng, giòn giã, rực rỡ."},{text:'Phân vân thì nghĩ nghĩa: "đôi <b>giày</b>" (đi ở chân) khác "quyển sách <b>dày</b>" (nhiều trang).'}]},{t:"tap",text:"Chạm vào các tiếng <b>viết sai</b> chính tả.",svg:g(["Trời","*nạnh,","bà","đi","đôi","*dày","mới","ra","vườn","hái","*dau."]),need:3,done:"Sửa lại: trời <b>lạnh</b>, đôi <b>giày</b>, hái <b>rau</b>."},{t:"try",q:{text:'Điền <b>l</b> hay <b>n</b>: "Mẹ đội chiếc …ón lá ra đồng." Gõ chữ cần điền.',input:!0,ans:"n",hint:"Đó là thứ đội trên đầu cho khỏi nắng.",why:'<b>nón</b> lá: tiếng "nón" viết n, tiếng "lá" viết l.'}},{t:"tip",text:"• d, gi, r và l, n: phải <b>hiểu nghĩa</b> rồi mới chọn chữ.<br>• Nhớ theo cặp: dịu dàng, giòn giã, rực rỡ, lo lắng, nắn nót.<br>• Hay gặp: <b>gi</b>ó, <b>gi</b>ày, <b>r</b>au, <b>r</b>ùa, <b>n</b>ước, <b>n</b>ón, <b>l</b>á, <b>l</b>úa."}],practice:[{id:"tv2.ct-drgi-ln.1",text:'Điền <b>d</b>, <b>gi</b> hay <b>r</b>: "Con …ùa bò chậm chạp."',opts:["d","gi","r"],ans:2,why:"<b>con rùa</b> viết r."},{id:"tv2.ct-drgi-ln.2",text:'Điền <b>l</b> hay <b>n</b>: "Mùa hè, trời …ắng chang chang."',opts:["n","l"],ans:0,why:'trời <b>nắng</b> viết n. Còn "lắng" dùng trong lắng nghe.'},{id:"tv2.ct-drgi-ln.3",text:"Từ nào viết <b>sai</b> chính tả?",opts:["cô giáo","dạy học","gia đình","dàu có"],ans:3,why:"Phải viết <b>giàu có</b> (gi). Các từ còn lại đều đúng."},{id:"tv2.ct-drgi-ln.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Bà lấu nồi canh rau.","Bà nấu nồi canh rau.","Bà nấu lồi canh dau."],ans:1,why:"<b>nấu</b> và <b>nồi</b> viết n, <b>rau</b> viết r."},{id:"tv2.ct-drgi-ln.5",text:'Điền <b>d</b> hay <b>gi</b>: "Cô …áo khen cả lớp." Gõ chữ cần điền.',input:!0,ans:"gi",why:"<b>cô giáo</b> viết gi."}]},{id:"tv2.ct-van",title:"Vần dễ lẫn",emoji:"🔔",min:6,who:"frog",cards:[{t:"say",pose:"wave",text:'Chào em, Ếch Cốm đây! "Bàn tay" hay "bàn tai"? "Ngôi sao" hay "ngôi sau"? Đọc nhanh nghe gần giống, nhưng viết sai vần là sai nghĩa đó!'},{t:"pic",svg:e([["✋","bàn t<b>ay</b>"],["👂","cái t<b>ai</b>"],["⭐","ngôi s<b>ao</b>"],["6️⃣","số s<b>áu</b>"]]),cap:"Đổi vần là đổi nghĩa: <b>tay – tai</b>, <b>sao – sáu</b>."},{t:"try",q:{text:'Chọn tiếng đúng: "Chú chim … hót líu lo."',opts:["sáu","sáo"],ans:1,hint:"Một tiếng là con chim, một tiếng là con số.",why:'<b>chim sáo</b>: vần ao. Còn "sáu" là số 6, vần au.'}},{t:"say",text:"Cặp <b>iu/ưu</b>: <b>dịu</b> dàng, cái <b>rìu</b>, <b>trĩu</b> quả – con <b>cừu</b>, quả <b>lựu</b>, <b>bưu</b> điện."},{t:"try",q:{text:"Từ nào viết <b>đúng</b> chính tả?",opts:["con cìu","quả lựu","cái rừu"],ans:1,hint:"Nhớ: con cừu, quả lựu (ưu); cái rìu (iu).",why:"Viết đúng: con <b>cừu</b>, quả <b>lựu</b>, cái <b>rìu</b>."}},{t:"say",text:"Cặp <b>uôn/uông</b> và <b>an/ang</b> khác nhau ở chữ <b>g</b> cuối: chuồn chuồn – cái chuông; bàn học – cây bàng."},{t:"tap",text:"Chạm vào các tiếng có vần <b>uông</b>.",svg:g(["cái","*chuông","chuồn","chuồn","*uống","nước","*luống","rau","buồn","ngủ","cuộn","len"]),need:3,done:"Có 3 tiếng vần uông: <b>chuông, uống, luống</b>. Còn chuồn, buồn, cuộn có vần <b>uôn</b> (không có g)."},{t:"try",q:{text:'Điền <b>an</b> hay <b>ang</b>: "Mẹ mua cho em chiếc b… học mới." Gõ vần cần điền (không cần dấu thanh).',input:!0,ans:"an",also:["àn"],hint:"Đó là cái em ngồi viết bài hằng ngày.",why:'<b>bàn</b> học: vần <b>an</b>. Còn "bàng" là tên một loài cây.'}},{t:"steps",title:"Cách chọn vần khi phân vân",items:[{text:"Đọc chậm cả từ, nghĩ xem từ đó <b>nghĩa là gì</b>."},{text:'Thử cả hai cách viết: "bàn tay" hay "bàn tai"? Cách nào đúng nghĩa với câu thì chọn.'},{text:"Nhớ các từ hay gặp: bay lượn (ay), chào hỏi (ao), màu sắc (au), cái chuông (uông), cây bàng (ang)."}]},{t:"try",q:{text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Máy bai bay qua làng.","Máy bay bay qua làn.","Máy bay bay qua làng."],ans:2,hint:'Xét kĩ tiếng "bay" và tiếng "làng".',why:"<b>máy bay</b> (vần ay), <b>làng</b> quê (vần ang)."}},{t:"tip",text:"• ai/ay, ao/au, iu/ưu: đọc chậm, nghĩ <b>nghĩa</b> rồi mới viết.<br>• uông, ang có thêm chữ <b>g</b> ở cuối: chuông, bàng.<br>• Phân vân: thử cả hai cách, chọn cách đúng nghĩa với câu."}],practice:[{id:"tv2.ct-van.1",text:'Chọn tiếng đúng: "Em giơ … xin phát biểu."',opts:["tay","tai"],ans:0,why:'Giơ <b>tay</b> (vần ay). "Tai" là cái để nghe.'},{id:"tv2.ct-van.2",text:'Chọn tiếng đúng: "Mẹ mua cho em một quả … đỏ mọng."',opts:["lịu","lựu"],ans:1,why:"quả <b>lựu</b>: vần ưu."},{id:"tv2.ct-van.3",text:"Tiếng nào có vần <b>uôn</b>?",opts:["chuông","luống","chuồn","uống"],ans:2,why:"<b>chuồn</b> (chuồn chuồn) có vần uôn. Chuông, luống, uống có vần uông."},{id:"tv2.ct-van.4",text:"Câu nào viết <b>đúng</b> chính tả?",opts:["Trời sáng, đàn chim bai lượn.","Trời sáng, đàn chim bay lượng.","Trời xáng, đàn chim bay lượn.","Trời sáng, đàn chim bay lượn."],ans:3,why:"Viết đúng: trời <b>sáng</b>, <b>bay</b> (vần ay), <b>lượn</b> (vần ươn)."},{id:"tv2.ct-van.5",text:'Điền <b>ao</b> hay <b>au</b>: "Bông hoa có nhiều m… sắc rực rỡ." Gõ vần cần điền (không cần dấu thanh).',input:!0,ans:"au",also:["àu"],why:'<b>màu</b> sắc: vần <b>au</b>. ("mào" là cái mào của gà trống.)'}]},{id:"tv2.ct-viethoa",title:"Viết hoa đầu câu và tên riêng",emoji:"🔠",min:5,who:"panda",cards:[{t:"say",pose:"wave",text:"Chào em, Gấu Trúc Pu đây! Có hai chỗ em <b>luôn phải viết hoa</b>: chữ <b>đầu câu</b> và <b>tên riêng</b>."},{t:"pic",svg:g(["#{H}ôm","nay,","#{L}an","về","quê","ở","#{H}ải","#{D}ương."]),cap:"Chữ <b>H</b> đầu câu viết hoa. Tên bạn <b>Lan</b> và tên tỉnh <b>Hải Dương</b> cũng viết hoa."},{t:"say",text:"Ý 1 — <b>Đầu câu</b>: viết hoa chữ đầu tiên của câu, và chữ ngay <b>sau dấu chấm</b>, dấu chấm hỏi, dấu chấm than."},{t:"try",q:{text:'Bạn viết: "em đi học. trời rất đẹp." Những chữ nào cần viết hoa?',opts:["học và đẹp","em và trời","chỉ chữ em","đi và rất"],ans:1,hint:"Có hai câu. Chữ đầu của mỗi câu phải viết hoa.",why:'"Em" đứng đầu câu, "Trời" đứng sau dấu chấm: cả hai đều viết hoa.'}},{t:"say",text:"Ý 2 — <b>Tên người</b>: viết hoa chữ cái đầu của <b>mỗi tiếng</b> trong họ và tên: Nguyễn Minh Khang, Lê Thu Hà."},{t:"try",q:{text:'Viết tên bạn "trần thị mai" cho đúng thì phải viết hoa những chữ nào?',opts:["Chỉ chữ trần","Chữ trần và chữ mai","Cả ba chữ trần, thị, mai","Không chữ nào"],ans:2,hint:"Mỗi tiếng trong họ và tên đều viết hoa chữ cái đầu.",why:"Ba tiếng Trần, Thị, Mai đều viết hoa chữ cái đầu: <b>Trần Thị Mai</b>."}},{t:"say",text:'Ý 3 — <b>Tên địa danh</b> (tỉnh, thành phố, sông, núi…): viết hoa chữ đầu mỗi tiếng của tên: Hà Nội, Cần Thơ, sông Hồng, núi Ba Vì. Chữ "sông", "núi" đứng trước tên thì viết thường.'},{t:"tap",text:"Chạm vào các chữ <b>cần viết hoa</b> mà bạn lại viết thường.",svg:g(["Sáng","nay,","mẹ","đưa","em","và","bé","*lan","về","quê","ở","*huế.","*nhà","ông","bà","gần","sông","Hương."]),need:3,done:'Sửa lại: bé <b>Lan</b> (tên người), <b>Huế</b> (tên địa danh), <b>Nhà</b> (đầu câu, sau dấu chấm). Chữ "sông" viết thường là đúng.'},{t:"try",q:{text:"Xếp các từ thành câu đúng.",order:["Bạn","Minh","sống","ở","Đà","Nẵng."],ans:"Bạn Minh sống ở Đà Nẵng.",hint:'Từ có dấu chấm đứng cuối câu. "Bạn" đứng đầu câu.',why:'Bạn Minh sống ở Đà Nẵng. "Bạn" viết hoa vì đứng đầu câu; "Minh" là tên người; "Đà Nẵng" là tên thành phố.'}},{t:"tip",text:"• Viết hoa chữ <b>đầu câu</b> và chữ ngay sau dấu chấm, dấu chấm hỏi, dấu chấm than.<br>• Tên người: viết hoa chữ đầu <b>mỗi tiếng</b>: Lê Thu Hà.<br>• Tên địa danh: Hà Nội, Cần Thơ, sông Hồng, núi Ba Vì."}],practice:[{id:"tv2.ct-viethoa.1",text:'Viết tên thủ đô "hà nội" cho đúng thì phải viết hoa mấy chữ cái?',opts:["1 chữ","2 chữ","3 chữ"],ans:1,why:"Tên địa danh viết hoa chữ đầu mỗi tiếng: <b>H</b>à <b>N</b>ội, tức là 2 chữ cái."},{id:"tv2.ct-viethoa.2",text:'Câu "hôm qua, em gặp bạn Hoa." có chữ nào cần viết hoa mà chưa viết hoa?',opts:["hôm","em","gặp","bạn"],ans:0,why:"Chữ đầu câu phải viết hoa: <b>Hôm</b> qua, em gặp bạn Hoa."},{id:"tv2.ct-viethoa.3",text:'Bạn viết: "nhà bà ngoại em ở cần thơ." Những chữ nào cần viết hoa?',opts:["nhà, bà","nhà, cần, thơ","cần, thơ","nhà, ngoại, cần, thơ"],ans:1,why:'"Nhà" đứng đầu câu viết hoa; "Cần Thơ" là tên thành phố, viết hoa cả hai tiếng; "ngoại" viết thường.'},{id:"tv2.ct-viethoa.4",text:'Nam viết: "nghỉ hè, em được về quê thăm ông bà. ông bà rất vui." Nam cần sửa mấy chữ thành chữ viết hoa?',opts:["4 chữ","3 chữ","2 chữ","1 chữ"],ans:2,why:'Có 2 câu. Sửa chữ đầu mỗi câu: <b>Nghỉ</b> hè… và <b>Ông</b> bà rất vui. Chữ "ông" trong "thăm ông bà" đứng giữa câu nên giữ nguyên.'},{id:"tv2.ct-viethoa.5",text:"Xếp các từ thành câu đúng.",order:["Bà","em","ở","gần","núi","Ba","Vì."],ans:"Bà em ở gần núi Ba Vì.",why:'Bà em ở gần núi Ba Vì. "Bà" đứng đầu câu; "Ba Vì" là tên núi nên viết hoa cả hai tiếng, còn "núi" viết thường.'}]}]},{id:"dochieu",name:"Đọc hiểu",en:"Reading",icon:"📚",color:"#3d6ef7",lessons:[{id:"tv2.doc-chitiet",title:"Tìm chi tiết trong bài đọc",emoji:"🔎",min:5,who:"rabbit",cards:[{t:"say",pose:"wave",text:"Chào em, Thỏ Bông đây! Đọc hiểu giống như đi <b>tìm kho báu</b>: câu trả lời nằm sẵn trong bài. Em chỉ cần biết <b>tìm ở đâu</b>."},{t:"pic",svg:c("Rổ ổi của ông","Chủ nhật, Mai cùng bố về quê thăm ông bà. Vườn nhà ông có cây ổi sai trĩu quả. Ông hái cho Mai một rổ ổi chín thơm lừng. Mai chọn mấy quả to nhất, mang biếu bà. Bà xoa đầu Mai, khen: “Cháu bà ngoan quá!”"),cap:"Em đọc kĩ đoạn văn nhé. Các câu hỏi sau đều dựa vào bài này."},{t:"steps",title:"Bí kíp: nhìn từ để hỏi, biết ngay cần tìm gì",items:[{text:"<b>Ai?</b> → tìm tên người, con vật: Mai, bố, ông, bà."},{text:"<b>Ở đâu?</b> → tìm nơi chốn: ở quê, trong vườn."},{text:"<b>Khi nào?</b> → tìm thời gian: chủ nhật, buổi sáng, mùa hè…"},{text:"<b>Làm gì?</b> → tìm việc làm: hái ổi, chọn quả, biếu bà."}]},{t:"try",q:{text:"<b>Khi nào</b> Mai về quê?",opts:["Thứ bảy","Chủ nhật","Mùa hè","Buổi tối"],ans:1,hint:"Tìm từ chỉ thời gian ở câu đầu tiên của bài.",why:"Câu đầu: “<b>Chủ nhật</b>, Mai cùng bố về quê thăm ông bà.”"}},{t:"try",q:{text:"<b>Ai</b> hái ổi cho Mai?",opts:["Bố","Bà","Ông","Mai tự hái"],ans:2,hint:'Tìm câu có từ "hái".',why:"Bài viết: “<b>Ông</b> hái cho Mai một rổ ổi chín thơm lừng.”"}},{t:"say",text:'Gặp câu hỏi "<b>làm gì</b>", em tìm <b>từ chỉ hoạt động</b> trong bài: hái, chọn, mang, biếu…'},{t:"try",q:{text:"Mai <b>làm gì</b> với mấy quả ổi to nhất?",opts:["Ăn ngay","Cho bố","Mang về nhà","Mang biếu bà"],ans:3,hint:'Tìm câu có từ "to nhất".',why:"Bài viết: “Mai chọn mấy quả to nhất, <b>mang biếu bà</b>.”"}},{t:"tap",text:'Chạm vào các từ chỉ <b>thời gian</b> (trả lời câu hỏi "Khi nào?").',svg:g(["*Sáng sớm,","gà","gáy","vang.","*Buổi trưa,","mèo","nằm","ngủ.","*Tối đến,","cả","nhà","quây","quần."]),need:3,done:"<b>Sáng sớm, buổi trưa, tối đến</b> là các từ chỉ thời gian."},{t:"tip",text:"• Đọc kĩ câu hỏi, tìm <b>từ để hỏi</b>: Ai? Ở đâu? Khi nào? Làm gì?<br>• Quay lại bài, tìm câu có chứa ý đó.<br>• Chọn đáp án <b>đúng như bài viết</b>, không đoán theo ý mình."}],practice:[{id:"tv2.doc-chitiet.1",text:"Đọc bài rồi trả lời: chuyện xảy ra vào <b>mùa nào</b>?",svg:y,opts:["Mùa xuân","Mùa hè","Mùa thu","Mùa đông"],ans:1,why:"Câu đầu: “<b>Mùa hè</b>, Nam được nghỉ học.”"},{id:"tv2.doc-chitiet.2",text:"Mỗi sáng, Nam cùng <b>ai</b> ra vườn tưới rau?",svg:y,opts:["Bố","Mẹ","Bà","Bạn Vàng"],ans:2,why:"Bài viết: “Mỗi sáng, Nam cùng <b>bà</b> ra vườn tưới rau.” Vàng là chú chó chạy theo."},{id:"tv2.doc-chitiet.3",text:"Nam ngồi đọc truyện <b>ở đâu</b>?",svg:y,opts:["Bên hiên","Trong vườn","Ở lớp","Trong bếp"],ans:0,why:"Bài viết: “Nam ngồi <b>bên hiên</b> đọc truyện cho bà nghe.”"},{id:"tv2.doc-chitiet.4",text:"Buổi chiều, Nam <b>làm gì</b>?",svg:y,opts:["Tưới rau","Chơi với chó Vàng","Đi ngủ","Đọc truyện cho bà nghe"],ans:3,why:"Bài viết: “Buổi chiều, Nam ngồi bên hiên <b>đọc truyện cho bà nghe</b>.” Tưới rau là việc buổi sáng."},{id:"tv2.doc-chitiet.5",text:"Chú chó trong bài tên là gì? Gõ tên chú chó.",svg:y,input:!0,ans:"Vàng",also:["chó Vàng","chú chó Vàng"],why:"Bài viết: “Chú chó <b>Vàng</b> lon ton chạy theo.”"}]},{id:"tv2.doc-ychinh",title:"Ý chính và bài học của câu chuyện",emoji:"💡",min:6,who:"eleph",cards:[{t:"say",pose:"wave",text:"Chào em, Voi Bi đây! Đọc xong một câu chuyện, em thử tự hỏi: <b>Chuyện kể về điều gì?</b> và <b>Mình học được gì?</b>"},{t:"pic",svg:c("Chiếc bình hoa","Na chơi bóng trong nhà, lỡ làm vỡ chiếc bình hoa của mẹ. Na sợ lắm, định giấu đi. Nghĩ một lúc, Na chạy đến bên mẹ: “Mẹ ơi, con xin lỗi, con làm vỡ bình rồi.” Mẹ ôm Na: “Con biết nhận lỗi, mẹ vui lắm. Lần sau con nhớ chơi bóng ngoài sân nhé!”")},{t:"steps",title:"Tìm ý chính của câu chuyện",items:[{text:"Câu chuyện có ai? → <b>Na và mẹ</b>."},{text:"Chuyện gì xảy ra? → Na làm vỡ bình hoa."},{text:"Kết thúc ra sao? → Na <b>nhận lỗi</b>, mẹ vui."},{text:"Gộp lại: chuyện kể về <b>bạn Na làm vỡ bình và dũng cảm nhận lỗi</b>."}]},{t:"try",q:{text:"Câu chuyện chủ yếu kể về điều gì?",opts:["Na thích chơi bóng","Na làm vỡ bình và biết nhận lỗi","Mẹ mua bình hoa mới","Na giấu chiếc bình vỡ"],ans:1,hint:"Chọn câu nói được cả chuyện: chuyện gì xảy ra và kết thúc ra sao.",why:"Na làm vỡ bình rồi dũng cảm nhận lỗi. Na chỉ <b>định</b> giấu chứ không giấu, còn chơi bóng chỉ là một chi tiết nhỏ."}},{t:"say",text:"<b>Bài học</b> là điều tốt em mang theo sau khi đọc. Nó thường nằm ở <b>việc làm tốt</b> của nhân vật, hay ở <b>lời khen, lời khuyên</b> cuối truyện."},{t:"try",q:{text:"Em học được điều gì từ bạn Na?",opts:["Làm sai thì nên giấu đi","Không được chơi bóng","Làm sai thì dũng cảm nhận lỗi","Đồ vỡ thì mua cái mới"],ans:2,hint:"Mẹ khen Na vì việc gì?",why:"Mẹ khen: “Con biết nhận lỗi, mẹ vui lắm.” Bài học: <b>làm sai thì dũng cảm nhận lỗi</b>."}},{t:"say",pose:"cheer",text:"Giỏi lắm! Thử với một câu chuyện khác nhé."},{t:"pic",svg:c("Thỏ con chia bánh","Thỏ mẹ cho Thỏ con một chiếc bánh cà rốt thơm phức. Thỏ con định ăn ngay thì thấy Sóc nhỏ ngồi buồn thiu vì đói. Thỏ con bẻ đôi chiếc bánh, đưa Sóc một nửa. Hai bạn vừa ăn vừa cười vui vẻ. Thỏ con thấy chiếc bánh hôm nay ngon hơn mọi ngày.")},{t:"try",q:{text:"Câu chuyện muốn nói với em điều gì?",opts:["Bánh cà rốt rất ngon","Sóc nhỏ hay buồn","Nên ăn bánh thật nhanh","Biết chia sẻ, ta cũng thấy vui"],ans:3,hint:"Vì sao Thỏ con thấy chiếc bánh hôm nay ngon hơn?",why:"Thỏ con chia bánh cho bạn đói, hai bạn cùng vui. Bài học: <b>biết chia sẻ, ta cũng thấy vui</b>."}},{t:"try",q:{text:"Từ nào nói đúng về Thỏ con?",opts:["tốt bụng","lười biếng","nhút nhát"],ans:0,hint:"Thỏ con đã làm gì khi thấy bạn đói?",why:"Thỏ con bẻ đôi bánh cho bạn đang đói: Thỏ con <b>tốt bụng</b>."}},{t:"tip",text:"• <b>Ý chính</b>: chuyện kể về ai, chuyện gì xảy ra, kết thúc ra sao.<br>• <b>Bài học</b>: xem nhân vật làm việc gì tốt, ai khen, ai khuyên điều gì.<br>• Chọn câu nói được <b>cả câu chuyện</b>, không chọn một chi tiết nhỏ."}],practice:[{id:"tv2.doc-ychinh.1",text:"Đọc chuyện rồi trả lời: câu chuyện kể về ai?",svg:l,opts:["Mẹ Sẻ","Sẻ con","Bụi cỏ","Ngọn cây"],ans:1,why:"Nhân vật chính là <b>Sẻ con</b> đang tập bay."},{id:"tv2.doc-ychinh.2",text:"Lần đầu tập bay, chuyện gì xảy ra với Sẻ con?",svg:l,opts:["Bay lên ngọn cây","Bỏ cuộc","Bị lạc mẹ","Rơi xuống bụi cỏ"],ans:3,why:"Bài viết: “Lần đầu, Sẻ vừa rời tổ đã <b>rơi xuống bụi cỏ</b>.”"},{id:"tv2.doc-ychinh.3",text:"Câu chuyện chủ yếu kể về điều gì?",svg:l,opts:["Sẻ con kiên trì tập bay","Sẻ con bị ngã đau","Tổ chim trên cây","Mẹ Sẻ dạy con hát"],ans:0,why:"Sẻ ngã nhưng không bỏ cuộc, ngày nào cũng tập rồi bay được lên cao: chuyện kể về <b>Sẻ con kiên trì tập bay</b>."},{id:"tv2.doc-ychinh.4",text:"Em học được điều gì từ Sẻ con?",svg:l,opts:["Thấy khó thì nghỉ","Phải bay thật cao","Kiên trì sẽ làm được","Không nên ra khỏi nhà"],ans:2,why:"Sẻ con chăm tập mỗi ngày nên bay được. Bài học: <b>kiên trì sẽ làm được</b>."},{id:"tv2.doc-ychinh.5",text:"Xếp các từ thành câu mẹ Sẻ nói, câu nêu bài học của chuyện.",svg:l,order:["Chăm","tập","thì","sẽ","làm","được."],ans:"Chăm tập thì sẽ làm được.",why:"Mẹ Sẻ nói: “Chăm tập thì sẽ làm được.” Đây chính là bài học của câu chuyện."}]},{id:"tv2.doc-nghiatu",title:"Hiểu nghĩa của từ trong câu",emoji:"🧐",min:5,who:"monkey",cards:[{t:"say",pose:"wave",text:"Chào em, Khỉ Tít đây! Gặp từ lạ trong bài, đừng lo. Những chữ xung quanh sẽ <b>mách nhỏ</b> cho em nghĩa của nó."},{t:"pic",svg:c("","Vườn nhà ông có cây ổi <b>sai</b> trĩu quả."),cap:'"Sai" ở đây không phải "làm sai bài". Cây <b>sai</b> quả nghĩa là cây có <b>rất nhiều quả</b>.'},{t:"steps",title:"Ba bước đoán nghĩa của từ",items:[{text:"Bước 1: Đọc cả câu có từ đó, đọc cả câu trước và câu sau."},{text:"Bước 2: Nghĩ xem câu đang nói về gì: người, cây cối hay con vật…"},{text:"Bước 3: <b>Thay thử</b> nghĩa em chọn vào câu. Câu vẫn đúng ý là em đoán đúng!"}]},{t:"try",q:{text:'Đọc câu: "Chú chó nhỏ <b>lon ton</b> chạy theo bé." Từ "lon ton" tả điều gì?',opts:["Dáng chạy nhanh, bước ngắn","Tiếng sủa thật to","Bộ lông mềm mượt","Đứng yên một chỗ"],ans:0,hint:'Từ này đứng ngay trước từ "chạy".',why:'"lon ton chạy theo": từ này tả <b>dáng chạy</b> với những bước ngắn, nhanh nhẹn.'}},{t:"say",text:'Mẹo <b>thay thử</b>: "Mặt hồ <b>phẳng lặng</b>." Thay bằng "yên, không gợn sóng" → "Mặt hồ yên, không gợn sóng." Vẫn hợp ý, vậy là đúng nghĩa!'},{t:"try",q:{text:'"Bạn Hà <b>rụt rè</b> đứng nép sau lưng mẹ." Từ nào thay được cho "rụt rè"?',opts:["mạnh dạn","ngại ngùng","vui vẻ","nhanh nhẹn"],ans:1,hint:"Bạn đứng nép sau lưng mẹ, chắc là bạn đang thấy thế nào?",why:'Đứng nép sau lưng mẹ là đang ngại, chưa dám. Rụt rè = <b>ngại ngùng</b>. "Mạnh dạn" thì ngược nghĩa.'}},{t:"say",text:"Có khi đề hỏi từ <b>cùng nghĩa</b> (nghĩa giống nhau) hoặc từ <b>trái nghĩa</b> (nghĩa ngược nhau). Em vẫn thay thử vào câu để kiểm tra."},{t:"try",q:{text:'"Cánh đồng lúa chín <b>vàng óng</b>." Từ "vàng óng" nghĩa là gì?',opts:["vàng nhạt, xỉn màu","vàng lẫn xanh","vàng và bóng đẹp"],ans:2,hint:"Lúa chín đẹp nhất khi có màu thế nào?",why:"<b>vàng óng</b> là màu vàng và bóng, nhìn rất đẹp."}},{t:"try",q:{text:'"Cô giáo em rất <b>hiền hậu</b>." Từ nào <b>trái nghĩa</b> với "hiền hậu"?',opts:["hiền lành","dịu dàng","tốt bụng","dữ dằn"],ans:3,hint:'Trái nghĩa là nghĩa ngược lại. Ba từ kia gần nghĩa với "hiền hậu".',why:"Hiền lành, dịu dàng, tốt bụng gần nghĩa với hiền hậu. Từ trái nghĩa là <b>dữ dằn</b>."}},{t:"tip",text:"• Đọc cả câu và các câu xung quanh để đoán nghĩa.<br>• Một từ có thể có nhiều nghĩa: cây <b>sai</b> quả khác làm <b>sai</b> bài.<br>• <b>Thay thử</b> nghĩa em chọn vào câu: vẫn hợp ý là đúng."}],practice:[{id:"tv2.doc-nghiatu.1",text:'"Mẹ <b>âu yếm</b> ôm bé vào lòng." Từ "âu yếm" nghĩa là gì?',opts:["vội vàng, hấp tấp","giận dữ, bực bội","yêu thương, trìu mến","mệt mỏi, uể oải"],ans:2,why:"Mẹ ôm bé vào lòng là thể hiện tình thương. Âu yếm = <b>yêu thương, trìu mến</b>."},{id:"tv2.doc-nghiatu.2",text:'"Đàn chim <b>ríu rít</b> trên cành cây." Từ "ríu rít" tả điều gì?',opts:["Màu lông của chim","Tiếng chim hót vui tai","Cách chim làm tổ"],ans:1,why:"<b>ríu rít</b> tả tiếng chim kêu liên tiếp, trong và vui tai."},{id:"tv2.doc-nghiatu.3",text:'"Sân trường sau cơn mưa thật <b>sạch sẽ</b>." Từ nào <b>cùng nghĩa</b> với "sạch sẽ"?',opts:["sạch bong","bẩn thỉu","lộn xộn","ướt át"],ans:0,why:'<b>sạch bong</b> cũng nói là rất sạch. "Bẩn thỉu" là trái nghĩa.'},{id:"tv2.doc-nghiatu.4",text:'"Bạn Minh <b>chăm chỉ</b> học bài mỗi tối." Từ nào <b>trái nghĩa</b> với "chăm chỉ"?',opts:["siêng năng","cần cù","chịu khó","lười biếng"],ans:3,why:"Siêng năng, cần cù, chịu khó đều cùng nghĩa với chăm chỉ. Trái nghĩa là <b>lười biếng</b>."},{id:"tv2.doc-nghiatu.5",text:'"Cây bưởi nhà bà <b>sai</b> trĩu quả." Ở đây "sai" nghĩa là có rất … quả. Gõ từ còn thiếu.',input:!0,ans:"nhiều",why:"Cây <b>sai</b> quả là cây có rất <b>nhiều</b> quả, cành trĩu xuống."}]}]},{id:"viet",name:"Viết",en:"Writing",icon:"📝",color:"#8b5cf6",lessons:[{id:"tv2.viet-banthan",title:"Giới thiệu bản thân",emoji:"🙋",min:5,who:"dog",cards:[{t:"say",pose:"wave",text:"Chào em, Cún Đốm đây! Ngày đầu vào lớp mới, em muốn các bạn biết về mình. Mình cùng viết đoạn <b>giới thiệu bản thân</b> nhé!"},{t:"steps",title:"Dàn ý: trả lời lần lượt 4 câu hỏi",items:[{text:"1. Em tên là gì? Em mấy tuổi?"},{text:"2. Em học lớp nào, trường nào?"},{text:"3. Em thích làm gì? (sở thích)"},{text:"4. Em mơ ước điều gì? Em muốn nói gì với các bạn?"}]},{t:"pic",svg:c("Bài mẫu","Xin chào các bạn! Tớ tên là Lê Minh Anh, năm nay tớ bảy tuổi. Tớ học lớp 2A, Trường Tiểu học Sao Mai. Tớ rất thích vẽ tranh và đá cầu. Ước mơ của tớ là trở thành cô giáo. Tớ mong được làm quen với các bạn!"),cap:"Mỗi câu trả lời một câu hỏi trong dàn ý."},{t:"try",q:{text:'Trong bài mẫu, câu nào trả lời câu hỏi "<b>Em thích làm gì?</b>"',opts:["Tớ tên là Lê Minh Anh.","Tớ học lớp 2A.","Tớ rất thích vẽ tranh.","Tớ bảy tuổi."],ans:2,hint:'Tìm câu có từ "thích".',why:"“Tớ rất thích vẽ tranh và đá cầu.” nói về <b>sở thích</b>."}},{t:"say",text:'Viết hay hơn: thêm <b>một chi tiết nhỏ</b>. Thay vì "Tớ thích vẽ", hãy viết "Tớ thích vẽ những chú mèo con ngộ nghĩnh."'},{t:"try",q:{text:"Câu nào <b>không hợp</b> để đưa vào đoạn giới thiệu bản thân?",opts:["Tớ thích chơi cờ vua.","Tớ học lớp 2B.","Hôm qua trời mưa to.","Tớ tên là Bảo Ngọc."],ans:2,hint:"Câu nào không nói gì về bản thân em?",why:'"Hôm qua trời mưa to." nói về thời tiết, không giới thiệu gì về em.'}},{t:"try",q:{text:"Xếp các từ thành câu nói về ước mơ.",order:["Ước","mơ","của","em","là","làm","bác","sĩ."],ans:"Ước mơ của em là làm bác sĩ.",hint:"Chữ viết hoa đứng đầu câu, chữ có dấu chấm đứng cuối.",why:"Ước mơ của em là làm bác sĩ."}},{t:"say",text:'Nhớ nhé: viết hoa chữ đầu câu và tên riêng (tên em, tên trường), cuối câu có dấu chấm. Mở đầu có thể chào: "Xin chào các bạn!"'},{t:"try",q:{text:'Huy viết: "Tớ tên là trần gia huy." Bạn cần sửa gì?',opts:["Thêm dấu phẩy","Viết hoa tên: Trần Gia Huy","Bỏ dấu chấm cuối câu","Không cần sửa gì"],ans:1,hint:"Tên người viết thế nào?",why:"Tên người viết hoa chữ đầu mỗi tiếng: <b>Trần Gia Huy</b>."}},{t:"tip",text:"• Dàn ý: <b>tên, tuổi</b> → <b>lớp, trường</b> → <b>sở thích</b> → <b>ước mơ</b>.<br>• Mỗi ý viết 1–2 câu, thêm chi tiết cho sinh động.<br>• Viết hoa đầu câu và tên riêng, cuối câu có dấu chấm."}],practice:[{id:"tv2.viet-banthan.1",text:"Đoạn giới thiệu bản thân thường bắt đầu bằng ý nào?",opts:["Tên và tuổi của em","Sở thích của em","Ước mơ của em"],ans:0,why:"Giới thiệu thì nói <b>tên, tuổi</b> trước để các bạn biết em là ai."},{id:"tv2.viet-banthan.2",text:"Câu nào <b>không hợp</b> với đoạn giới thiệu bản thân?",opts:["Tớ rất thích bơi.","Con mèo nhà hàng xóm màu đen.","Tớ học lớp 2D.","Tớ mơ làm phi công."],ans:1,why:"Câu về con mèo nhà hàng xóm không nói gì về em."},{id:"tv2.viet-banthan.3",text:"Xếp các từ thành câu.",order:["Tớ","rất","thích","chơi","đá","cầu."],ans:"Tớ rất thích chơi đá cầu.",why:"Tớ rất thích chơi đá cầu."},{id:"tv2.viet-banthan.4",text:'Bạn viết: "tớ tên là mai anh" Câu này cần sửa thế nào?',opts:["Chỉ thêm dấu chấm cuối câu","Chỉ viết hoa Tớ, Mai, Anh","Viết hoa Tớ, Mai, Anh và thêm dấu chấm","Không cần sửa"],ans:2,why:"Chữ đầu câu viết hoa, tên người viết hoa mỗi tiếng, cuối câu có dấu chấm: <b>Tớ tên là Mai Anh.</b> Phải làm cả hai việc."},{id:"tv2.viet-banthan.5",text:"Câu nào nói về <b>ước mơ</b>?",opts:["Tớ thích ăn kem dâu.","Tớ học Trường Tiểu học Lê Lợi.","Tớ năm nay tám tuổi.","Lớn lên, tớ muốn làm chú bộ đội."],ans:3,why:'"Lớn lên, tớ muốn làm…" nói điều em mong sau này: đó là <b>ước mơ</b>.'}]},{id:"tv2.viet-kechuyen",title:"Kể một việc em đã làm",emoji:"🌱",min:6,who:"pengu",cards:[{t:"say",pose:"wave",text:"Chào em, Cánh Cụt Pin đây! Gần đây em đã làm việc gì có ích? Tưới cây, quét nhà, gấp quần áo… Mình cùng <b>kể lại</b> thành đoạn văn nhé!"},{t:"steps",title:"Dàn ý: 4 câu hỏi gợi ý",items:[{text:"1. <b>Khi nào</b>, em làm việc gì?"},{text:"2. Em làm việc đó <b>như thế nào</b>? (làm gì trước, làm gì sau)"},{text:"3. Kết quả ra sao?"},{text:"4. Em <b>cảm thấy</b> thế nào?"}]},{t:"pic",svg:c("Bài mẫu","Chiều thứ bảy, em giúp mẹ tưới cây ngoài ban công. Đầu tiên, em hứng đầy nước vào bình tưới. Sau đó, em tưới nhẹ vào gốc từng chậu hoa. Cuối cùng, em nhặt những chiếc lá vàng bỏ vào thùng rác. Mấy chậu hoa tươi tắn hẳn lên. Em thấy rất vui vì đã làm được việc có ích."),cap:"Các từ <b>Đầu tiên, Sau đó, Cuối cùng</b> giúp kể đúng thứ tự."},{t:"try",q:{text:'Trong bài mẫu, câu nào trả lời câu hỏi "<b>Khi nào, em làm việc gì?</b>"',opts:["Mấy chậu hoa tươi tắn hẳn lên.","Chiều thứ bảy, em giúp mẹ tưới cây.","Em thấy rất vui."],ans:1,hint:"Tìm câu có từ chỉ thời gian.",why:"“<b>Chiều thứ bảy</b>, em giúp mẹ <b>tưới cây</b>…” vừa nói khi nào, vừa nói việc gì."}},{t:"say",text:"Từ nối giúp đoạn văn đi <b>đúng thứ tự</b>: Đầu tiên → Sau đó → Tiếp theo → Cuối cùng."},{t:"try",q:{text:"Xếp các câu theo đúng thứ tự việc làm.",...w(["Đầu tiên, em lấy chổi.","Sau đó, em quét sạch nhà.","Cuối cùng, em đổ rác."]),hint:"Nhìn từ nối ở đầu mỗi câu.",why:"Đầu tiên → Sau đó → Cuối cùng: lấy chổi, quét nhà, rồi đổ rác."}},{t:"say",text:"Cuối đoạn, nhớ nói <b>cảm nghĩ</b> của em: em thấy vui, tự hào, hay thấy mình đã lớn hơn."},{t:"try",q:{text:"Câu nào nói <b>cảm nghĩ</b> của em?",opts:["Em cầm chổi quét nhà.","Hôm đó là chủ nhật.","Em thấy mình thật có ích.","Nhà em có ba phòng."],ans:2,hint:"Cảm nghĩ là em thấy thế nào trong lòng.",why:'"Em <b>thấy</b> mình thật có ích." nói lên cảm nghĩ của em.'}},{t:"try",q:{text:'Em đã quét nhà xong. Chọn từ nối hợp nhất: "…, em cất chổi vào góc nhà."',opts:["Đầu tiên","Cuối cùng","Hôm qua là"],ans:1,hint:"Cất chổi là việc làm trước hay sau cùng?",why:"Cất chổi là việc làm sau cùng, nên dùng <b>Cuối cùng</b>."}},{t:"tip",text:"• Dàn ý: <b>khi nào, làm việc gì</b> → <b>làm thế nào</b> → <b>kết quả</b> → <b>cảm nghĩ</b>.<br>• Dùng từ nối: Đầu tiên, Sau đó, Cuối cùng.<br>• Kể việc em <b>thật sự</b> đã làm, viết 4–5 câu."}],practice:[{id:"tv2.viet-kechuyen.1",text:"Đoạn văn kể việc em đã làm nên bắt đầu bằng ý nào?",opts:["Em cảm thấy thế nào","Kết quả ra sao","Khi nào, em làm việc gì","Em làm như thế nào"],ans:2,why:"Mở đầu cho biết <b>khi nào</b> và <b>việc gì</b>, rồi mới kể cách làm, kết quả, cảm nghĩ."},{id:"tv2.viet-kechuyen.2",text:"Xếp các câu theo đúng thứ tự việc làm.",...w(["Đầu tiên, em trải chăn ra.","Sau đó, em gấp đôi chăn.","Cuối cùng, em cất chăn."]),why:"Đầu tiên trải chăn, sau đó gấp đôi, cuối cùng cất chăn đi."},{id:"tv2.viet-kechuyen.3",text:"Câu nào <b>không</b> nên có trong đoạn văn kể việc em tưới cây?",opts:["Em rất thích xem phim hoạt hình.","Em xách bình nước ra vườn.","Em tưới đều cho từng gốc cây.","Cây xanh tốt hẳn lên."],ans:0,why:"Câu về phim hoạt hình không liên quan đến việc tưới cây."},{id:"tv2.viet-kechuyen.4",text:'Chọn từ nối hợp nhất: "Em rửa sạch bát. …, em úp bát lên giá cho ráo nước."',opts:["Đầu tiên","Sau đó","Hôm qua"],ans:1,why:"Úp bát là việc làm <b>sau</b> khi rửa, nên dùng <b>Sau đó</b>."},{id:"tv2.viet-kechuyen.5",text:"Câu nào hợp làm câu <b>kết</b> đoạn văn kể việc em giúp bà nhặt rau?",opts:["Sáng chủ nhật, em giúp bà nhặt rau.","Em nhặt bỏ lá úa, giữ lại lá non.","Em rửa rau thật sạch.","Bà khen em ngoan, em vui lắm."],ans:3,why:"Câu kết nói kết quả và cảm nghĩ: <b>Bà khen em ngoan, em vui lắm.</b> Câu đầu tiên là câu mở đầu."}]},{id:"tv2.viet-dovat",title:"Tả đồ vật, đồ chơi",emoji:"🧸",min:6,who:"dino",cards:[{t:"say",pose:"wave",text:"Chào em, Khủng Long Rex đây! Em có món đồ chơi nào yêu thích không? Gấu bông, ô tô, búp bê… Hôm nay mình học <b>tả</b> nó thật đáng yêu!"},{t:"steps",title:"Dàn ý tả đồ chơi",items:[{text:"1. Giới thiệu: đó là đồ chơi gì? Ai tặng, khi nào?"},{text:"2. Tả <b>hình dáng, màu sắc</b>: to hay nhỏ, màu gì, có gì đặc biệt?"},{text:"3. Em <b>chơi</b> với nó thế nào?"},{text:"4. Tình cảm của em, em <b>giữ gìn</b> nó ra sao?"}]},{t:"pic",svg:c("Bài mẫu","Sinh nhật vừa rồi, bố tặng em một chú gấu bông. Chú gấu to bằng cái gối ôm, bộ lông màu nâu mềm mượt. Đôi mắt chú tròn xoe, đen láy như hai hạt nhãn. Tối nào em cũng ôm chú đi ngủ. Em rất yêu chú gấu và luôn giữ chú sạch sẽ."),cap:"Từ tả <b>màu sắc</b>: nâu, đen láy · <b>hình dáng</b>: to, tròn xoe · khi sờ vào: mềm mượt."},{t:"tap",text:"Chạm vào các từ <b>tả đặc điểm</b> của chú gấu.",svg:g(["Chú","gấu","có","bộ","lông","*mềm mượt,","đôi","mắt","*tròn xoe","và","cái","mũi","*đen láy."]),need:3,done:"<b>mềm mượt, tròn xoe, đen láy</b> là các từ tả đặc điểm."},{t:"say",text:'Bí kíp tả hay: dùng <b>so sánh</b>. "Mắt tròn xoe" → "Mắt tròn xoe <b>như hai hạt nhãn</b>." Đọc lên là thấy ngay!'},{t:"try",q:{text:"Câu nào có hình ảnh <b>so sánh</b>?",opts:["Chiếc ô tô màu đỏ.","Bánh xe tròn như cái cúc áo.","Em thích chiếc ô tô.","Ô tô chạy bằng pin."],ans:1,hint:'Tìm câu có từ "như".',why:'"Bánh xe tròn <b>như</b> cái cúc áo": so sánh bánh xe với cái cúc áo.'}},{t:"try",q:{text:"Câu nào tả <b>màu sắc</b> của con búp bê?",opts:["Búp bê mặc váy hồng.","Búp bê cao bằng gang tay.","Mẹ mua búp bê ở chợ.","Em chải tóc cho búp bê."],ans:0,hint:"Tìm câu có từ chỉ màu.",why:'"váy <b>hồng</b>": hồng là từ chỉ màu sắc.'}},{t:"try",q:{text:"Xếp các từ thành câu tả đồ chơi.",order:["Quả","bóng","nhựa","tròn","xoe,","màu","xanh","lá."],ans:"Quả bóng nhựa tròn xoe, màu xanh lá.",hint:"Chữ viết hoa đứng đầu, chữ có dấu chấm đứng cuối.",why:"Quả bóng nhựa tròn xoe, màu xanh lá. Câu tả cả hình dáng (tròn xoe) và màu sắc (xanh lá)."}},{t:"try",q:{text:"Câu nào hợp làm câu <b>kết</b> bài tả đồ chơi?",opts:["Con rô bốt cao bằng gang tay.","Rô bốt có đôi mắt đèn xanh.","Bố mua rô bốt ở siêu thị.","Em luôn cất rô bốt cẩn thận vào hộp."],ans:3,hint:"Câu kết nói tình cảm của em, em giữ gìn đồ chơi ra sao.",why:'"Em luôn cất rô bốt cẩn thận vào hộp." nói việc em <b>giữ gìn</b> đồ chơi, hợp làm câu kết.'}},{t:"tip",text:'• Dàn ý: <b>giới thiệu</b> → <b>hình dáng, màu sắc</b> → <b>cách chơi</b> → <b>tình cảm, giữ gìn</b>.<br>• Dùng từ tả: tròn xoe, mềm mượt, đỏ tươi…<br>• Thêm <b>so sánh</b> với từ "như" cho bài văn sinh động.'}],practice:[{id:"tv2.viet-dovat.1",text:"Khi tả đồ chơi, phần đầu tiên nên viết gì?",opts:["Em chơi với nó thế nào","Giới thiệu đó là đồ chơi gì","Tình cảm của em"],ans:1,why:"Mở bài <b>giới thiệu</b> đó là đồ chơi gì, ai tặng, rồi mới tả và kể cách chơi."},{id:"tv2.viet-dovat.2",text:"Từ nào tả <b>hình dáng</b>?",opts:["đỏ tươi","mềm mại","tròn vo","thơm phức"],ans:2,why:"<b>tròn vo</b> tả hình dáng. Đỏ tươi là màu sắc, mềm mại là khi sờ, thơm phức là mùi."},{id:"tv2.viet-dovat.3",text:"Câu nào có hình ảnh <b>so sánh</b>?",opts:["Chiếc diều cong như vầng trăng.","Chiếc diều có đuôi dài.","Chiếc diều bay cao.","Em thả diều với bố."],ans:0,why:'"Chiếc diều cong <b>như</b> vầng trăng": so sánh chiếc diều với vầng trăng.'},{id:"tv2.viet-dovat.4",text:"Xếp các từ thành câu kết bài tả đồ chơi.",order:["Em","sẽ","giữ","gìn","đồ","chơi","thật","cẩn","thận."],ans:"Em sẽ giữ gìn đồ chơi thật cẩn thận.",why:"Em sẽ giữ gìn đồ chơi thật cẩn thận."},{id:"tv2.viet-dovat.5",text:'Đọc đoạn: "Chiếc ô tô của em màu vàng. Bánh xe đen bóng. Em hay cho ô tô chở mấy con gấu nhỏ." Đoạn văn còn <b>thiếu</b> phần nào?',opts:["Tả màu sắc","Tả bánh xe","Cách em chơi","Tình cảm của em"],ans:3,why:"Đoạn đã có màu sắc (vàng), bánh xe (đen bóng), cách chơi (chở gấu). Còn thiếu <b>tình cảm của em</b> với chiếc ô tô."}]},{id:"tv2.viet-loinoi",title:"Lời cảm ơn, xin lỗi, lời chúc, tin nhắn",emoji:"💌",min:6,who:"uni",cards:[{t:"say",pose:"wave",text:"Chào em, Kỳ Lân Sao đây! Một lời <b>cảm ơn</b>, một lời <b>xin lỗi</b> hay một tấm <b>thiệp</b> nhỏ có thể làm người khác vui cả ngày đó!"},{t:"pic",svg:e([["🙏","Cảm ơn"],["🙇","Xin lỗi"],["🎂","Lời chúc"],["✉️","Tin nhắn"]]),cap:"Bốn kiểu lời nói, lời viết em dùng hằng ngày."},{t:"say",text:'<b>Cảm ơn</b> khi được giúp đỡ, được tặng quà. <b>Xin lỗi</b> khi làm sai, làm phiền người khác. Với người lớn, nhớ nói <b>lễ phép</b>: "Cháu cảm ơn bà ạ!"'},{t:"try",q:{text:"Em lỡ giẫm vào chân bạn. Em nói gì?",opts:["Ai bảo cậu đứng đây!","Tớ xin lỗi, cậu có đau không?","Cảm ơn cậu nhé!"],ans:1,hint:"Em làm bạn đau, em cần nói lời gì?",why:"Làm bạn đau thì <b>xin lỗi</b> và hỏi han bạn."}},{t:"try",q:{text:"Bác hàng xóm cho em quả ổi. Em nói thế nào cho <b>lễ phép</b>?",opts:["Cháu cảm ơn bác ạ!","Cảm ơn nhé!","Ổi ngon quá!","Cho cháu thêm nữa."],ans:0,hint:'Với người lớn, nhớ xưng "cháu" và thêm "ạ".',why:'Được cho quà thì cảm ơn. Với người lớn: "<b>Cháu cảm ơn bác ạ!</b>"'}},{t:"say",text:"<b>Lời chúc</b> và <b>thiệp</b>: ghi tên người nhận, viết lời chúc, rồi ghi tên em. Ví dụ thiệp sinh nhật tặng bạn:"},{t:"pic",svg:c("🎉 Thiệp sinh nhật 🎉","Gửi Bình thân mến!<br>Chúc cậu tuổi mới thật vui, học giỏi và chăm ngoan. Mong cậu mãi là bạn thân của tớ!<br><i>Bạn của cậu: Lan</i>"),cap:"Thiệp có 3 phần: <b>gửi ai</b> → <b>lời chúc</b> → <b>tên người viết</b>."},{t:"try",q:{text:"Lời chúc nào hợp để tặng <b>bà</b> nhân ngày sinh nhật?",opts:["Chúc cậu học thật giỏi nhé!","Chúc bạn có nhiều đồ chơi!","Cháu chúc bà sống lâu, vui vẻ!"],ans:2,hint:"Em là cháu của bà. Em xưng thế nào?",why:'Với bà, em xưng "cháu" và chúc điều hợp với người già: "<b>Cháu chúc bà sống lâu, vui vẻ!</b>"'}},{t:"say",text:"<b>Tin nhắn</b> để báo cho người nhà khi họ vắng nhà. Cần ghi: <b>gửi ai</b>, <b>việc cần báo</b> (đi đâu, mấy giờ về) và <b>ai viết</b>."},{t:"steps",title:"Viết tin nhắn cho mẹ: em sang nhà bạn Hà học nhóm",items:[{text:"Gửi ai: <b>Mẹ ơi,</b>"},{text:"Việc cần báo: <b>con sang nhà bạn Hà học nhóm, 5 giờ chiều con về.</b>"},{text:"Ai viết: <b>Con: Minh</b>"},{text:"Đọc lại: đủ ba phần, viết hoa đúng, có dấu câu."}]},{t:"try",q:{text:'Minh viết: "Mẹ ơi, con sang nhà bạn Hà học nhóm. Con: Minh." Tin nhắn còn thiếu điều gì?',opts:["Hôm nay trời nắng","Mấy giờ con về","Tên con vật nuôi"],ans:1,hint:"Mẹ đọc tin nhắn sẽ muốn biết thêm điều gì?",why:"Tin nhắn đã có gửi ai, đi đâu, ai viết. Còn thiếu <b>mấy giờ con về</b> để mẹ yên tâm."}},{t:"tip",text:'• <b>Cảm ơn</b> khi được giúp; <b>xin lỗi</b> khi làm sai. Với người lớn thêm "ạ".<br>• <b>Thiệp</b>: gửi ai → lời chúc → tên em.<br>• <b>Tin nhắn</b>: gửi ai → việc cần báo (đi đâu, mấy giờ về) → ai viết.'}],practice:[{id:"tv2.viet-loinoi.1",text:"Bạn cho em mượn bút. Em nói gì?",opts:["Tớ xin lỗi!","Cảm ơn cậu nhé!","Chúc mừng cậu!"],ans:1,why:"Được bạn giúp thì nói lời <b>cảm ơn</b>."},{id:"tv2.viet-loinoi.2",text:"Em làm đổ nước ra bàn của bạn. Em nói gì?",opts:["Tớ xin lỗi, để tớ lau nhé!","Cảm ơn cậu!","Tại cậu để cốc ở đó!","Chúc cậu vui!"],ans:0,why:"Em làm sai thì <b>xin lỗi</b> và sửa lỗi: lau khô bàn cho bạn."},{id:"tv2.viet-loinoi.3",text:"Thiệp chúc mừng thường <b>kết thúc</b> bằng gì?",opts:["Lời chúc","Tên người nhận","Tên người viết"],ans:2,why:"Thiệp: gửi ai → lời chúc → cuối cùng là <b>tên người viết</b>."},{id:"tv2.viet-loinoi.4",text:"Xếp các từ thành lời chúc tặng cô giáo.",order:["Em","chúc","cô","luôn","vui","vẻ","ạ!"],ans:"Em chúc cô luôn vui vẻ ạ!",why:'Em chúc cô luôn vui vẻ ạ! Với cô giáo, em xưng "em" và thêm "ạ" cho lễ phép.'},{id:"tv2.viet-loinoi.5",text:"Tin nhắn nào viết <b>đủ</b> các phần cần có?",opts:["Bố ơi, con đi đá bóng, 5 giờ con về.","Bố ơi, con đi đá bóng. Con: Nam.","Con đi đá bóng, 5 giờ con về. Con: Nam.","Bố ơi, con đi đá bóng, 5 giờ về. Con: Nam."],ans:3,why:"Đủ ba phần: gửi ai (Bố ơi), việc cần báo (đi đá bóng, 5 giờ về), ai viết (Con: Nam). Các tin kia đều thiếu một phần."}]},{id:"tv2.viet-tinhcam",title:"Đoạn văn nói về người thân",emoji:"❤️",min:6,who:"pig",cards:[{t:"say",pose:"wave",text:"Chào em, Heo Ủn đây! Trong nhà, em yêu ai nhất? Ông, bà, bố, mẹ hay anh chị? Hôm nay mình viết đoạn văn nói <b>tình cảm</b> của em với người thân."},{t:"steps",title:"Dàn ý: 4 câu hỏi gợi ý",items:[{text:"1. Người thân em muốn kể là <b>ai</b>?"},{text:"2. Người đó có <b>đặc điểm</b> gì? (dáng người, mái tóc, tính tình)"},{text:"3. Người đó thường <b>làm gì</b> cho em? Em nhớ nhất kỉ niệm nào?"},{text:"4. <b>Tình cảm</b> của em với người đó thế nào?"}]},{t:"pic",svg:c("Bài mẫu","Người em yêu quý nhất là bà nội. Năm nay bà đã bảy mươi tuổi. Tóc bà bạc trắng như mây, nụ cười rất hiền. Tối nào bà cũng kể chuyện cổ tích cho em nghe. Em rất yêu bà. Em mong bà sống thật lâu với con cháu.")},{t:"try",q:{text:"Trong bài mẫu, câu nào nói <b>tình cảm</b> của em với bà?",opts:["Tóc bà bạc trắng như mây.","Năm nay bà bảy mươi tuổi.","Em rất yêu bà.","Bà kể chuyện cổ tích."],ans:2,hint:"Tìm câu có từ chỉ tình cảm như yêu, thương, quý.",why:'"Em rất <b>yêu</b> bà." nói tình cảm của em. Các câu kia tả đặc điểm hoặc kể việc bà làm.'}},{t:"say",text:"Từ ngữ chỉ tình cảm: <b>yêu quý, kính yêu, thương, biết ơn, nhớ</b>. Dùng đúng chỗ, đoạn văn sẽ ấm áp hơn."},{t:"tap",text:"Chạm vào các từ chỉ <b>tình cảm</b>.",svg:g(["*yêu quý","mái tóc","*biết ơn","nấu cơm","*kính yêu","đôi mắt","*thương","chăm chỉ"]),need:4,done:'<b>yêu quý, biết ơn, kính yêu, thương</b> là từ chỉ tình cảm. "Chăm chỉ" chỉ tính nết, "nấu cơm" chỉ hoạt động.'},{t:"try",q:{text:'Chọn từ hợp nhất: "Em rất … mẹ vì mẹ luôn chăm sóc em."',opts:["giận","biết ơn","sợ","quên"],ans:1,hint:"Mẹ chăm sóc em, em thấy thế nào với mẹ?",why:"Mẹ chăm sóc em nên em <b>biết ơn</b> mẹ."}},{t:"say",text:'Viết hay hơn: kể <b>một việc cụ thể</b>. Không chỉ "Mẹ rất tốt", mà "Những đêm mất điện, mẹ ngồi quạt cho em ngủ."'},{t:"try",q:{text:"Câu nào kể <b>việc cụ thể</b> người thân làm cho em?",opts:["Bố thường dạy em đi xe đạp.","Bố em rất là tốt bụng.","Bố em là một người bố."],ans:0,hint:"Việc cụ thể là việc em nhìn thấy được: bố làm gì?",why:'"Bố thường <b>dạy em đi xe đạp</b>." kể một việc cụ thể. Câu kia chỉ khen chung chung.'}},{t:"try",q:{text:"Xếp các từ thành câu nói tình cảm với mẹ.",order:["Con","yêu","mẹ","nhiều","lắm!"],ans:"Con yêu mẹ nhiều lắm!",hint:"Chữ viết hoa đứng đầu, chữ có dấu chấm than đứng cuối.",why:"Con yêu mẹ nhiều lắm!"}},{t:"tip",text:"• Dàn ý: <b>là ai</b> → <b>đặc điểm</b> → <b>việc làm, kỉ niệm</b> → <b>tình cảm của em</b>.<br>• Dùng từ chỉ tình cảm: yêu quý, kính yêu, biết ơn.<br>• Kể một <b>việc cụ thể</b> để đoạn văn chân thật, cảm động."}],practice:[{id:"tv2.viet-tinhcam.1",text:"Câu nào hợp làm câu <b>mở đầu</b> đoạn văn về người thân?",opts:["Em mong bà sống lâu.","Người em yêu nhất là bà.","Bà hay nấu chè cho em."],ans:1,why:'Mở đầu nói người thân em muốn kể là <b>ai</b>: "Người em yêu nhất là bà."'},{id:"tv2.viet-tinhcam.2",text:"Từ nào chỉ <b>tình cảm</b>?",opts:["hiền hậu","bạc trắng","kính yêu","cao lớn"],ans:2,why:"<b>kính yêu</b> chỉ tình cảm. Hiền hậu là tính tình, bạc trắng và cao lớn tả hình dáng."},{id:"tv2.viet-tinhcam.3",text:"Câu nào tả <b>đặc điểm</b> của ông?",opts:["Ông có chòm râu bạc phơ.","Em rất kính yêu ông.","Em mong ông vui.","Hôm nay ông đi chợ."],ans:0,why:'"chòm râu <b>bạc phơ</b>" tả đặc điểm của ông.'},{id:"tv2.viet-tinhcam.4",text:"Xếp các từ thành câu.",order:["Em","sẽ","chăm","ngoan","để","bố","mẹ","vui","lòng."],ans:"Em sẽ chăm ngoan để bố mẹ vui lòng.",why:"Em sẽ chăm ngoan để bố mẹ vui lòng."},{id:"tv2.viet-tinhcam.5",text:'Đọc đoạn: "Mẹ em là cô giáo. Mẹ có mái tóc dài. Tối nào mẹ cũng kèm em học bài." Đoạn văn còn <b>thiếu</b> ý nào?',opts:["Người đó là ai","Đặc điểm của mẹ","Việc mẹ làm cho em","Tình cảm của em với mẹ"],ans:3,why:"Đoạn đã có: là ai (mẹ, cô giáo), đặc điểm (tóc dài), việc làm (kèm em học). Còn thiếu <b>tình cảm của em</b> với mẹ."}]}]}])})();
